<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('sales.create')&&!can('reports.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT s.*,COALESCE(c.name,"Walk-in Customer") customer,c.customer_code,c.phone,c.address,u.display_name cashier FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.created_by WHERE s.id=?');$s->execute([$id]);$sale=$s->fetch();if(!$sale){http_response_code(404);exit('Sale not found');}$i=$db->prepare('SELECT si.*,p.item_code,p.name,p.barcode FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?');$i->execute([$id]);$items=$i->fetchAll();$p=$db->prepare('SELECT * FROM sale_payments WHERE sale_id=?');$p->execute([$id]);$payments=$p->fetchAll();$profit=array_sum(array_column($items,'gross_profit'));page_start('Invoice '.$sale['sale_no'],'sales_list.php');?>
<?php $rp=$db->prepare('SELECT cp.id payment_id,cp.receipt_no,cp.payment_date,cp.amount,cp.method,cp.reference_no,cpa.amount allocated_amount,u.display_name collector FROM customer_payment_allocations cpa JOIN customer_payments cp ON cp.id=cpa.payment_id JOIN users u ON u.id=cp.collected_by WHERE cpa.sale_id=? ORDER BY cp.payment_date,cp.id');$rp->execute([$id]);$laterPayments=$rp->fetchAll();?>
<?php $invoicePaymentHistory=[];$runningBalance=(float)$sale['total'];foreach($payments as $pay){$amount=(float)$pay['amount'];$runningBalance=max(0,$runningBalance-$amount);$invoicePaymentHistory[]=['receipt'=>'Initial payment','date'=>$sale['sale_date'],'method'=>$pay['method'],'reference'=>$pay['reference_no']??'','amount'=>$amount,'balance'=>$runningBalance];}foreach($laterPayments as $pay){$amount=(float)$pay['allocated_amount'];$runningBalance=max(0,$runningBalance-$amount);$invoicePaymentHistory[]=['receipt'=>$pay['receipt_no'],'date'=>$pay['payment_date'],'method'=>$pay['method'],'reference'=>$pay['reference_no']??'','amount'=>$amount,'balance'=>$runningBalance];}?><script>window.invoicePaymentHistory=<?=json_encode($invoicePaymentHistory,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;</script>
<?php if($sale['payment_type']==='credit'&&(float)$sale['balance']>0&&$sale['customer_id']&&can('payments.view')):?><section class="invoice-credit-action"><div><span class="step-number">Rs</span><div><b>Credit payment still due: <?=money($sale['balance'])?></b><p>Record money received for this exact invoice. Its balance and the customer account will update together.</p></div></div><a class="btn primary" href="payments.php?customer_id=<?=$sale['customer_id']?>&sale_id=<?=$sale['id']?>#receive-payment">+ Receive Credit Payment</a></section><?php endif;?>
<section class="invoice-tools"><?php if(can('reports.view')):?><a class="btn secondary" href="edit_record.php?type=sale&id=<?=$sale['id']?>">Correct Invoice Details</a><?php endif;?><?php if($sale['customer_id']):?><a class="btn secondary" href="customer_view.php?id=<?=$sale['customer_id']?>">View Customer Account</a><?php endif;?></section>
<?php if($laterPayments):?><section class="invoice-receipts panel"><div><span class="eyebrow">Credit payments received later</span><h3><?=count($laterPayments)?> receipt(s) applied to this invoice</h3></div><div class="receipt-list"><?php foreach($laterPayments as $pay):?><article><div><b><?=e($pay['receipt_no'])?></b><small><?=date('d M Y, H:i',strtotime($pay['payment_date']))?> · <?=e(str_replace('_',' ',$pay['method']))?></small><?php if(can('payments.view')):?><a class="row-edit" href="edit_record.php?type=customer_payment&id=<?=$pay['payment_id']?>">Correct receipt details</a><?php endif;?></div><strong><?=money($pay['allocated_amount'])?></strong></article><?php endforeach;?></div></section><?php endif;?>
<style>.invoice-credit-action{background:#fff7e5;border:1px solid #ecd7a5;border-left:5px solid #b4771e;border-radius:14px;padding:17px 20px;margin-bottom:14px;display:flex;align-items:center;justify-content:space-between;gap:18px}.invoice-credit-action>div{display:flex;align-items:center;gap:13px}.invoice-credit-action p{margin:4px 0 0;color:#718078}.invoice-tools{display:flex;justify-content:flex-end;gap:9px;margin-bottom:14px}.invoice-receipts{margin-bottom:16px;padding:18px 22px}.invoice-receipts h3{margin:5px 0 12px}.receipt-list{display:grid;gap:7px}.receipt-list article{display:flex;align-items:center;justify-content:space-between;background:#f7f9f6;border-radius:9px;padding:10px 13px}.receipt-list article div{display:flex;flex-direction:column}.receipt-list small{color:#718078;margin-top:3px}.receipt-list strong{color:#28784a}.selected-invoice{background:#fff7e5;border:1px solid #ecd7a5;border-radius:10px;padding:11px 13px;margin-bottom:14px;display:flex;flex-direction:column}.selected-invoice span{font-size:9px;text-transform:uppercase;color:#8a641e}.selected-invoice strong{color:#b23a34;margin-top:4px}@media(max-width:700px){.invoice-credit-action{align-items:stretch;flex-direction:column}.invoice-credit-action .btn{text-align:center}.invoice-tools{flex-direction:column}}</style>
<div class="invoice-actions"><a class="btn secondary" href="sales_list.php">← All Sales</a><button class="btn primary" onclick="window.print()">Print / Save PDF</button></div><section class="invoice panel"><header><div><span class="brand-mark">SG</span><div><h2>Supun Group</h2><p>Retail & Wholesale Electronics</p></div></div><div class="right"><span class="eyebrow">Sale invoice</span><h2><?=e($sale['sale_no'])?></h2><p><?=date('d F Y, h:i A',strtotime($sale['sale_date']))?></p></div></header><div class="invoice-meta"><div><span>Customer</span><b><?=e($sale['customer'])?></b><p><?=e($sale['phone']??'')?> <?=e($sale['address']??'')?></p></div><div><span>Sale type</span><b><?=e(ucfirst($sale['sale_type']))?></b></div><div><span>Payment</span><b><?=e(ucfirst($sale['payment_type']))?></b><p><?=e(ucwords(str_replace('_',' ',$sale['status'])))?></p></div><div><span>Cashier</span><b><?=e($sale['cashier'])?></b></div></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Barcode</th><th>Qty</th><th class="right">Price</th><th class="right">Discount</th><th>Warranty</th><th class="right">Total</th><?php if(user()['role_code']!=='cashier'):?><th class="right cost-col">Saved Cost</th><th class="right cost-col">Profit</th><?php endif;?></tr></thead><tbody><?php foreach($items as $r):?><tr><td><b><?=e($r['item_code'])?></b><br><?=e($r['name'])?></td><td><?=e($r['barcode']??'—')?></td><td><?=e($r['quantity'])?></td><td class="right"><?=money($r['unit_price'])?></td><td class="right"><?=money($r['discount'])?></td><td><?=$r['warranty_months']?(int)$r['warranty_months'].' months':'No warranty'?></td><td class="right"><b><?=money($r['line_total'])?></b></td><?php if(user()['role_code']!=='cashier'):?><td class="right cost-col"><?=money((float)$r['historical_unit_cost']*(float)$r['quantity'])?></td><td class="right cost-col"><?=money($r['gross_profit'])?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><div class="invoice-bottom"><div><h3>Payments</h3><?php if(!$payments):?><p>No payment received when invoice was created.</p><?php endif;?><?php foreach($payments as $pay):?><p><b><?=money($pay['amount'])?></b> by <?=e(str_replace('_',' ',$pay['method']))?> <?=e($pay['reference_no']??'')?></p><?php endforeach;?><p class="muted">Notes: <?=e($sale['notes']?:'None')?></p></div><div class="totals"><p><span>Subtotal</span><b><?=money($sale['subtotal'])?></b></p><p><span>Discount</span><b><?=money($sale['discount'])?></b></p><p class="grand"><span>Total</span><strong><?=money($sale['total'])?></strong></p><p><span>Paid</span><b><?=money($sale['paid_amount'])?></b></p><p><span>Balance</span><b><?=money($sale['balance'])?></b></p><?php if(user()['role_code']!=='cashier'):?><p class="cost-col"><span>Gross profit</span><b><?=money($profit)?></b></p><?php endif;?></div></div></section><style>.invoice-actions{display:flex;justify-content:space-between;margin-bottom:16px}.invoice{max-width:1200px;margin:auto}.invoice header{display:flex;justify-content:space-between;align-items:start;padding-bottom:22px;border-bottom:2px solid #174e39}.invoice header>div:first-child{display:flex;gap:12px}.invoice header h2{margin:0}.invoice header p{margin:5px 0;color:#718078}.invoice-meta{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:18px;padding:20px 0}.invoice-meta span{display:block;text-transform:uppercase;font-size:9px;color:#718078}.invoice-meta p{margin:4px 0;color:#718078}.invoice-bottom{display:grid;grid-template-columns:1fr 360px;gap:30px;padding-top:24px}.totals p{display:flex;justify-content:space-between}.totals .grand{border-top:2px solid #17211b;border-bottom:2px solid #17211b;padding:13px 0;font-size:19px}@media(max-width:700px){.invoice-meta,.invoice-bottom{grid-template-columns:1fr}}@media print{.sidebar,.topbar,.invoice-actions{display:none!important}.app{margin:0!important;width:100%!important}.content{padding:0!important}.invoice{border:0!important;box-shadow:none!important}.cost-col{display:none!important}}</style><?php page_end();
